import type { TableName } from '../db'

declare global {
    namespace Now {
        /**
         * Marks a record for deletion by coalesce keys.
         *
         * @param table - The target table name (e.g. `'sys_user_role'`)
         * @param keys - An object of coalesce key-value pairs used to uniquely identify the record
         *
         * @example
         * ```ts
         * Now.del('sys_user_role', { name: 'x_myapp.obsolete_role' })
         * ```
         */
        function del(table: TableName, keys: { [key: string]: string }): void
        /**
         * Marks a record for deletion by sys_id GUID.
         *
         * Use this to delete OOB (out-of-box) records by their sys_id.
         * For records created in Fluent, prefer removing the code instead -
         * the delete will be tracked automatically.
         *
         * @param table - The target table name (e.g. `'sys_hub_flow'`)
         * @param guid - A 32-character sys_id GUID
         *
         * @example
         * ```ts
         * Now.del('sys_hub_flow', 'a1b2c3d4e5f67890a1b2c3d4e5f67890')
         * ```
         */
        function del(table: TableName, guid: string): void
    }
}
